   "12\uac1c \ud654\uba74 \uc5b8\uc5b4\ub85c \ub2e4\uad6d\uc5b4 \uac00\uc815\ub3c4 \uc9d1\uc5d0\uc11c \uc27d\uac8c \uc5f0\uc2b5\ud574\uc694."
